{"path":"expo-app/src/screens/SignInScreen.tsx","content":"import React, { useState } from 'react';
import { SafeAreaView, View, Text, ActivityIndicator, StyleSheet, TouchableOpacity, Platform } from 'react-native';
import axios from 'axios';
import { useNavigation } from '@react-navigation/native';
import { saveToken } from '../auth';
import { API_URL } from '../config';
import { theme } from '../theme';
import PrimaryButton from '../components/PrimaryButton';
import LoadingOverlay from '../components/LoadingOverlay';
import { FontAwesome } from '@expo/vector-icons';
import FormField from '../components/ui/FormField';

export default function SignInScreen() {
  const navigation = useNavigation<any>();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [errorEmail, setErrorEmail] = useState('');
  const [errorPassword, setErrorPassword] = useState('');
  const [secureEntry, setSecureEntry] = useState(true);

  const validate = () => {
    let valid = true;
    if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
      setErrorEmail('Enter a valid email address.');
      valid = false;
    } else {
      setErrorEmail('');
    }
    if (!password || password.length < 12) {
      setErrorPassword('Password must be at least 12 characters, include uppercase, lowercase, number, and symbol.');
      valid = false;
    } else {
      setErrorPassword('');
    }
    return valid;
  };

  const handleLogin = async () => {
    if (!validate()) return;
    setLoading(true);
    try {
      const resp = await axios.post(`${API_URL}/auth/login`, { email, password });
      const token = resp.data.access_token;
      await saveToken(token);
      navigation.reset({ index: 0, routes: [{ name: 'Main' }] });
    } catch (e) {
      // Show error toast
    } finally {
      setLoading(false);
    }
  };

  return (
    <SafeAreaView style={styles.container}>
      <Text style={styles.title}>Welcome back</Text>
      <FormField
        label="Email address"
        value={email}
        onChangeText={setEmail}
        error={!!errorEmail}
        helperText={errorEmail}
        keyboardType="email-address"
        accessibilityLabel="Email address"
      />
      <FormField
        label="Password"
        value={password}
        onChangeText={setPassword}
        error={!!errorPassword}
        helperText={errorPassword}
        secureTextEntry={secureEntry}
        accessibilityLabel="Password"
        right={<TextInput.Icon name={secureEntry ? 'eye-off' : 'eye'} onPress={() => setSecureEntry(!secureEntry)} accessibilityLabel={secureEntry ? 'Show password' : 'Hide password'} />}
      />
      {loading ? (
        <ActivityIndicator size="large" color={theme.colors.primary} />
      ) : (
        <PrimaryButton title="Log in" onPress={handleLogin} accessibilityLabel="Log in" />
      )}
      <TouchableOpacity
        onPress={() => navigation.navigate('SignUp')}
        accessibilityRole="link"
        accessibilityLabel="Don’t have an account? Sign up"
        style={styles.link}
        accessible={true}
      >
        <Text style={styles.linkText}>Don’t have an account? Sign up</Text>
      </TouchableOpacity>
      {loading && <LoadingOverlay message="Signing you in…" />}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: theme.spacing.lg, backgroundColor: theme.colors.background },
  title: { ...theme.typography.h2, color: theme.colors.onSurface, marginBottom: theme.spacing.lg },
  link: { marginTop: theme.spacing.lg, alignItems: 'center' },
  linkText: { color: theme.colors.secondary, ...theme.typography.body, textDecorationLine: 'underline' },
});"}

{"path": "expo-app/src/screens/DashboardScreen.tsx", "content": "import React, { useEffect, useState } from 'react';
import { ActivityIndicator, StyleSheet, Text, View } from 'react-native';
import axios from 'axios';
import { useNavigation, useIsFocused, useRoute } from '@react-navigation/native';
import { getToken } from '../auth';
import { API_URL } from '../config';
import { theme } from '../theme';
import PrimaryButton from '../components/ui/PrimaryButton';
import Screen from '../components/ui/Screen';
import SummaryCard from '../components/ui/SummaryCard';
import EmptyState from '../components/ui/EmptyState';
import { FAB } from 'react-native-paper';

export default function DashboardScreen() {
  const navigation = useNavigation<any>();
  const route = useRoute<any>();
  const isFocused = useIsFocused();
  const [loading, setLoading] = useState(false);
  const [summary, setSummary] = useState<any>(null);
  const [receipts, setReceipts] = useState<any[]>([]);
  const [showMessage, setShowMessage] = useState(false);

  const fetchData = async () => {
    setLoading(true);
    try {
      const token = await getToken();
      const [summaryResp, receiptsResp] = await Promise.all([
        axios.get(`${API_URL}/dashboard`, { headers: { Authorization: `Bearer ${token}` } }),
        axios.get(`${API_URL}/receipts`, { headers: { Authorization: `Bearer ${token}` } }),
      ]);
      setSummary(summaryResp.data);
      setReceipts(receiptsResp.data);
    } catch (e) {
      // handle error
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (isFocused) {
      fetchData();
      if (route.params?.receiptSaved) {
        setShowMessage(true);
        navigation.setParams({ receiptSaved: false });
      }
    }
  }, [isFocused, route.params?.receiptSaved]);

  useEffect(() => {
    if (showMessage) {
      const timer = setTimeout(() => setShowMessage(false), 3000);
      return () => clearTimeout(timer);
    }
  }, [showMessage]);

  if (loading) {
    return (
      <View style={styles.center} accessibilityRole="none">
        <ActivityIndicator size="large" color={theme.colors.primary} />
        <Text style={styles.loadingText}>Loading summary…</Text>
      </View>
    );
  }

  const empty = !summary || (summary.income === 0 && summary.expenses === 0 && summary.mileage_deduction === 0 && summary.estimated_tax === 0);

  return (
    <Screen scroll>
      {showMessage && <Text style={styles.toast} accessibilityRole="alert">Receipt saved.</Text>}
      {empty ? (
        <EmptyState
          title="No data yet"
          description="You haven’t added any receipts or mileage yet. Tap the + button to get started."
          ctaLabel="Add first receipt"
          onPressCTA={() => navigation.navigate('ReceiptCapture')}
        />
      ) : (
        <>
          <View style={styles.cards}>
            <SummaryCard title="Income" value={`$${summary.income.toFixed(2)}`} accessibilityLabel="Income" />
            <SummaryCard title="Expenses" value={`$${summary.expenses.toFixed(2)}`} accessibilityLabel="Expenses" />
            <SummaryCard title="Mileage deduction" value={`$${summary.mileage_deduction.toFixed(2)}`} accessibilityLabel="Mileage deduction" />
            <SummaryCard title="Estimated tax" value={`$${summary.estimated_tax.toFixed(2)}`} accessibilityLabel="Estimated tax" />
          </View>
          <View style={styles.receiptList}>
            {receipts.map((r) => (
              <View key={r.id} style={styles.receiptItem} accessibilityLabel={`Receipt ${r.id}`}>
                <Text style={styles.receiptAmount}>{r.amount}</Text>
                <Text style={styles.receiptCategory}>{r.category}</Text>
              </View>
            ))}
          </View>
        </>
      )}
      <FAB
        icon="plus"
        onPress={() => navigation.navigate('ReceiptCapture')}
        style={styles.fab}
        accessibilityLabel="Add receipt"
        accessibilityRole="button"
      />
    </Screen>
  );
}

const styles = StyleSheet.create({
  center: { flex: 1, justifyContent: 'center', alignItems: 'center' },
  loadingText: { marginTop: theme.spacing.md, ...theme.typography.body },
  toast: { backgroundColor: theme.colors.success, color: theme.colors.onSuccess, padding: theme.spacing.sm, marginBottom: theme.spacing.md, textAlign: 'center', ...theme.typography.body },
  cards: { flexDirection: 'column' },
  receiptList: { marginTop: theme.spacing.lg },
  receiptItem: { flexDirection: 'row', justifyContent: 'space-between', paddingVertical: theme.spacing.sm, borderBottomWidth: 1, borderBottomColor: theme.colors.outline },
  receiptAmount: { ...theme.typography.body, color: theme.colors.onSurface },
  receiptCategory: { ...theme.typography.body, color: theme.colors.secondary },
  fab: { position: 'absolute', right: theme.spacing.lg, bottom: theme.spacing.lg },
});"}

