{"path": "expo-app/src/components/ui/FormField.tsx", "content": "import React from 'react';
import { TextInput, HelperText } from 'react-native-paper';
import { theme } from '../../theme';

type Props = {
  label: string;
  value: string;
  onChangeText: (text: string) => void;
  error?: boolean;
  helperText?: string;
  secureTextEntry?: boolean;
  keyboardType?: string;
  accessibilityLabel?: string;
  right?: React.ReactNode;
};

export default function FormField({ label, value, onChangeText, error, helperText, secureTextEntry, keyboardType, accessibilityLabel, right }: Props) {
  return (
    <>
      <TextInput
