{"path": "expo-app/App.tsx", "content": "import React, { useEffect, useState } from 'react';
import { NavigationContainer } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { createBottomTabNavigator } from '@react-navigation/bottom-tabs';
import { View, ActivityIndicator, Pressable } from 'react-native';
import { FontAwesome } from '@expo/vector-icons';
import { SafeAreaProvider } from 'react-native-safe-area-context';
import SignInScreen from './src/screens/SignInScreen';
import SignUpScreen from './src/screens/SignUpScreen';
import DashboardScreen from './src/screens/DashboardScreen';
import ReceiptCaptureScreen from './src/screens/ReceiptCaptureScreen';
import MileageEntryScreen from './src/screens/MileageEntryScreen';
import ExportScreen from './src/screens/ExportScreen';
import { theme } from './src/theme';
import { getToken } from './src/auth';
import Header from './src/components/Header';
import { Provider as PaperProvider, MD3LightTheme } from 'react-native-paper';

const Stack = createNativeStackNavigator();
const Tab = createBottomTabNavigator();

// Merge design tokens with Paper theme
const paperTheme = {
  ...MD3LightTheme,
  roundness: theme.radii.md,
  colors: {
    ...MD3LightTheme.colors,
    primary: theme.colors.primary,
    secondaryContainer: theme.colors.accent,
    onPrimary: theme.colors.onPrimary,
    background: theme.colors.background,
    surface: theme.colors.surface,
    onSurface: theme.colors.onSurface,
    error: theme.colors.error,
    onError: theme.colors.onError,
  },
};

function MainTabs() {
  return (
    // @ts-ignore
    <Tab.Navigator
      screenOptions={{
        headerShown: false,
        tabBarStyle: { backgroundColor: theme.colors.background, height: 56 },
        tabBarActiveTintColor: theme.colors.primary,
        tabBarInactiveTintColor: theme.colors.secondary,
        tabBarShowLabel: true,
        tabBarLabelStyle: { fontSize: 12 },
        tabBarButton: (props) => {
          const { onPress, accessibilityState, accessibilityLabel, style, children } = props as any;
          const focused = accessibilityState?.selected;
          const focusStyle = focused ? { borderWidth: 2, borderColor: theme.colors.primary } : {};
          return (
            <Pressable
              onPress={onPress}
              accessibilityRole="tab"
              accessibilityState={{ selected: accessibilityState?.selected }}
              accessibilityLabel={accessibilityLabel}
              style={[style, focusStyle]}
            >
              {children}
            </Pressable>
          );
        },
        unmountOnBlur: true,
      }}
    >
      <Tab.Screen
        name="Dashboard"
        component={DashboardScreen}
        options={{
          title: 'Dashboard',
          tabBarIcon: ({ color }) => <FontAwesome name="home" size={24} color={color} accessibilityLabel="Dashboard tab icon" />, 
          tabBarAccessibilityLabel: 'Dashboard',
        }}
      />
      <Tab.Screen
        name="ReceiptCapture"
        component={ReceiptCaptureScreen}
        options={{
          title: 'Add Receipt',
          tabBarIcon: ({ color }) => <FontAwesome name="camera" size={24} color={color} accessibilityLabel="Add Receipt tab icon" />, 
          tabBarAccessibilityLabel: 'Add Receipt',
        }}
      />
      <Tab.Screen
        name="Mileage"
        component={MileageEntryScreen}
        options={{
          title: 'Mileage',
          tabBarIcon: ({ color }) => <FontAwesome name="car" size={24} color={color} accessibilityLabel="Mileage tab icon" />, 
          tabBarAccessibilityLabel: 'Mileage',
        }}
      />
      <Tab.Screen
        name="Export"
        component={ExportScreen}
        options={{
          title: 'Export',
          tabBarIcon: ({ color }) => <FontAwesome name="download" size={24} color={color} accessibilityLabel="Export tab icon" />, 
          tabBarAccessibilityLabel: 'Export',
        }}
      />
    </Tab.Navigator>
  );
}

function MainWithHeader() {
  return (
    <View style={{ flex: 1 }}>
      <Header />
      <MainTabs />
    </View>
  );
}

export default function App() {
  const [loading, setLoading] = useState(true);
  const [initialRoute, setInitialRoute] = useState<'Auth' | 'Main'>('Auth');

  useEffect(() => {
    async function checkToken() {
      const token = await getToken();
      setInitialRoute(token ? 'Main' : 'Auth');
      setLoading(false);
    }
    checkToken();
  }, []);

  if (loading) {
    return (
      <View style={{ flex:1, justifyContent:'center', alignItems:'center' }} accessibilityRole="alert">
        <ActivityIndicator size="large" color={theme.colors.primary} />
      </View>
    );
  }

  return (
    <SafeAreaProvider>
      <PaperProvider theme={paperTheme}>
        <NavigationContainer>
          <Stack.Navigator screenOptions={{ headerShown:false }} initialRouteName={initialRoute === 'Main' ? 'Main' : 'Auth'}>
            <Stack.Screen name="Auth" component={AuthStack} />
            <Stack.Screen name="Main" component={MainWithHeader} />
          </Stack.Navigator>
        </NavigationContainer>
      </PaperProvider>
    </SafeAreaProvider>
  );
}

function AuthStack() {
  return (
    <Stack.Navigator screenOptions={{ headerShown:false }}>
      <Stack.Screen name="SignIn" component={SignInScreen} />
      <Stack.Screen name="SignUp" component={SignUpScreen} />
    </Stack.Navigator>
  );
}
"}

{"path": "expo-app/src/screens/DashboardScreen.tsx", "content": "import React, { useEffect, useState } from 'react';
import { ActivityIndicator, StyleSheet, Text, View, Pressable } from 'react-native';
import axios from 'axios';
import { useNavigation, useIsFocused, useRoute } from '@react-navigation/native';
import { getToken } from '../auth';
import { API_URL } from '../config';
import { theme } from '../theme';
import PrimaryButton from '../components/ui/PrimaryButton';
import Screen from '../components/ui/Screen';
import SummaryCard from '../components/ui/SummaryCard';
import EmptyState from '../components/ui/EmptyState';
import { FontAwesome } from '@expo/vector-icons';

export default function DashboardScreen() {
  const navigation = useNavigation<any>();
  const route = useRoute<any>();
  const isFocused = useIsFocused();
  const [loading, setLoading] = useState(false);
  const [summary, setSummary] = useState<any>(null);
  const [receipts, setReceipts] = useState<any[]>([]);
  const [showMessage, setShowMessage] = useState(false);

  const fetchData = async () => {
    setLoading(true);
    try {
      const token = await getToken();
      const [summaryResp, receiptsResp] = await Promise.all([
        axios.get(`${API_URL}/dashboard`, { headers: { Authorization: `Bearer ${token}` } }),
        axios.get(`${API_URL}/receipts`, { headers: { Authorization: `Bearer ${token}` } }),
      ]);
      setSummary(summaryResp.data);
      setReceipts(receiptsResp.data);
    } catch (e) {
      // handle error
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (isFocused) {
      fetchData();
      if (route.params?.receiptSaved) {
        setShowMessage(true);
        navigation.setParams({ receiptSaved: false });
      }
    }
  }, [isFocused, route.params?.receiptSaved]);

  useEffect(() => {
    if (showMessage) {
      const timer = setTimeout(() => setShowMessage(false), 3000);
      return () => clearTimeout(timer);
    }
  }, [showMessage]);

  if (loading) {
    return (
      <View style={styles.center} accessibilityRole="none">
        <ActivityIndicator size="large" color={theme.colors.primary} />
        <Text style={styles.loadingText}>Loading summary…</Text>
      </View>
    );
  }

  const empty = !summary || (summary.income === 0 && summary.expenses === 0 && summary.mileage_deduction === 0 && summary.estimated_tax === 0);

  return (
    <Screen scroll>
      {showMessage && <Text style={styles.toast} accessibilityRole="alert">Receipt saved.</Text>}
      {empty ? (
        <EmptyState
          title="No data yet"
          description="You haven’t added any receipts or mileage yet. Tap the + button to get started."
          ctaLabel="Add first receipt"
          onPressCTA={() => navigation.navigate('ReceiptCapture')}
        />
      ) : (
        <>
          <View style={styles.cards}>
            <SummaryCard title="Income" value={`$${summary.income.toFixed(2)}`} accessibilityLabel="Income" />
            <SummaryCard title="Expenses" value={`$${summary.expenses.toFixed(2)}`} accessibilityLabel="Expenses" />
            <SummaryCard title="Mileage deduction" value={`$${summary.mileage_deduction.toFixed(2)}`} accessibilityLabel="Mileage deduction" />
            <SummaryCard title="Estimated tax" value={`$${summary.estimated_tax.toFixed(2)}`} accessibilityLabel="Estimated tax" />
          </View>
          <View style={styles.receiptList}>
            {receipts.map((r) => (
              <View key={r.id} style={styles.receiptItem} accessibilityLabel={`Receipt ${r.id}`}>
                <Text style={styles.receiptAmount}>{r.amount}</Text>
                <Text style={styles.receiptCategory}>{r.category}</Text>
              </View>
            ))}
          </View>
        </>
      )}
      <Pressable
        onPress={() => navigation.navigate('ReceiptCapture')}
        accessibilityLabel="Add receipt"
        accessibilityRole="button"
        style={styles.fabButton}
      >
        <FontAwesome name="plus" size={24} color={theme.colors.onAccent} accessible={false} />
      </Pressable>
    </Screen>
  );
}

const styles = StyleSheet.create({
  center: { flex: 1, justifyContent: 'center', alignItems: 'center' },
  loadingText: { marginTop: theme.spacing.md, ...theme.typography.bodyMedium },
  toast: { backgroundColor: theme.colors.success, color: theme.colors.onSuccess, padding: theme.spacing.sm, marginBottom: theme.spacing.md, textAlign: 'center', ...theme.typography.bodyMedium },
  cards: { flexDirection: 'column' },
  receiptList: { marginTop: theme.spacing.lg },
  receiptItem: { flexDirection: 'row', justifyContent: 'space-between', paddingVertical: theme.spacing.sm, borderBottomWidth: 1, borderBottomColor: theme.colors.outline },
  receiptAmount: { ...theme.typography.bodyMedium, color: theme.colors.onSurface },
  receiptCategory: { ...theme.typography.bodyMedium, color: theme.colors.secondary },
  fabButton: {
    position: 'absolute',
    right: theme.spacing.lg,
    bottom: theme.spacing.lg,
    width: 56,
    height: 56,
    borderRadius: 28,
    backgroundColor: theme.colors.accent,
    alignItems: 'center',
    justifyContent: 'center',
  },
});"}

