{"path": "expo-app/src/screens/ReceiptCaptureScreen.tsx", "content": "import React, { useState } from 'react';
import { View, Text, ActivityIndicator, Alert, StyleSheet, Image, ScrollView, Platform, Pressable } from 'react-native';
import * as ImagePicker from 'expo-image-picker';
import axios from 'axios';
import { useNavigation } from '@react-navigation/native';
import { getToken } from '../auth';
import { API_URL } from '../config';
import { theme } from '../theme';
import PrimaryButton from '../components/ui/PrimaryButton';
import FormField from '../components/ui/FormField';
import Screen from '../components/ui/Screen';
import { TextInput } from 'react-native-paper';

export default function ReceiptCaptureScreen() {
  const navigation = useNavigation<any>();
  const [hasPermission, setHasPermission] = useState<boolean | null>(null);
  const [image, setImage] = useState<any>(null);
  const [amount, setAmount] = useState('');
  const [date, setDate] = useState('');
  const [category, setCategory] = useState('');
  const [notes, setNotes] = useState('');
  const [loading, setLoading] = useState(false);

  const requestPermission = async () => {
    const { status } = await ImagePicker.requestCameraPermissionsAsync();
    setHasPermission(status === 'granted');
  };

  const pickImage = async () => {
    const result = await ImagePicker.launchImageLibraryAsync({
      mediaTypes: ImagePicker.MediaTypeOptions.Images,
      quality: 1,
    });
    if (!result.canceled) {
      setImage(result);
    }
  };

  const takePhoto = async () => {
    const result = await ImagePicker.launchCameraAsync({
      mediaTypes: ImagePicker.MediaTypeOptions.Images,
      quality: 1,
    });
    if (!result.canceled) {
      setImage(result);
    }
  };

  const handlePlaceholderPress = async () => {
    await pickImage();
  };

  const handleSave = async () => {
    if (!amount || !date || !category) {
      Alert.alert('Error', 'Please fill all required fields.');
      return;
    }
    setLoading(true);
    try {
      const token = await getToken();
      const form = new FormData();
      form.append('amount', amount);
      form.append('date', date);
      form.append('category', category);
      form.append('notes', notes);
      if (image) {
        if (Platform.OS === 'web') {
          const resp = await fetch(image.assets[0].uri);
          const blob = await resp.blob();
          form.append('image', blob, image.assets[0].name || 'receipt.jpg');
        } else {
          form.append('image', {
            uri: image.assets[0].uri,
            name: image.assets[0].name || 'receipt.jpg',
            type: image.assets[0].type || 'image/jpeg',
          } as any);
        }
      } else {
        const placeholder = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/5+hHgAFgwJ/9YX8WAAAAABJRU5ErkJggg==';
        if (Platform.OS === 'web') {
          const resp = await fetch(placeholder);
          const blob = await resp.blob();
          form.append('image', blob, 'receipt.jpg');
        } else {
          form.append('image', {
            uri: placeholder,
            name: 'receipt.jpg',
            type: 'image/png',
          } as any);
        }
      }
      await axios.post(`${API_URL}/receipts`, form, {
        headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'multipart/form-data' },
      });
      navigation.navigate('Dashboard', { receiptSaved: true });
    } catch (e) {
      Alert.alert('Error', 'Upload failed. Check your connection and try again.');
    } finally {
      setLoading(false);
    }
  };

  if (hasPermission === false) {
    return (
      <Screen scroll>
        <Text style={styles.text}>Camera access denied. You can select a photo from the library.</Text>
        <PrimaryButton title="Choose from library" onPress={pickImage} accessibilityLabel="Choose from library" />
        {renderForm()}
      </Screen>
    );
  }

  if (hasPermission === null) {
    return (
      <Screen scroll>
        <Text style={styles.heading}>New receipt</Text>
        <Text style={styles.text}>Camera access needed</Text>
        <PrimaryButton title="Allow" onPress={requestPermission} accessibilityLabel="Allow" />
        <PrimaryButton title="Deny" onPress={() => setHasPermission(false)} accessibilityLabel="Deny" />
      </Screen>
    );
  }

  function renderForm() {
    return (
      <View style={styles.form}>
        <Text style={styles.heading}>New receipt</Text>
        {image && (
          <Image source={{ uri: image.assets[0].uri }} style={styles.image} accessibilityLabel="Receipt photo" accessibilityRole="image" />
        )}
        {!image && (
          <Pressable
            onPress={handlePlaceholderPress}
            accessibilityRole="button"
            accessibilityLabel="Tap to take a photo or choose from library"
            style={styles.placeholderContainer}
          >
            <Text style={styles.placeholderText}>Tap to take a photo or choose from library</Text>
          </Pressable>
        )}
        {Platform.OS !== 'web' && (
          <>
            <PrimaryButton title="Take photo" onPress={takePhoto} accessibilityLabel="Take photo" />
            <PrimaryButton title="Choose from library" onPress={pickImage} accessibilityLabel="Choose from library" />
          </>
        )}
        <FormField label="Amount (USD)" value={amount} onChangeText={setAmount} keyboardType="numeric" accessibilityLabel="Amount (USD)" />
        <FormField label="Date" value={date} onChangeText={setDate} accessibilityLabel="Date" />
        <FormField label="Category" value={category} onChangeText={setCategory} accessibilityLabel="Category" />
        <FormField label="Notes (optional)" value={notes} onChangeText={setNotes} accessibilityLabel="Notes (optional)" />
        {loading ? (
          <ActivityIndicator size="large" color={theme.colors.primary} />
        ) : (
          <PrimaryButton title="Save receipt" onPress={handleSave} accessibilityLabel="Save receipt" />
        )}
      </View>
    );
  }

  return (
    <ScrollView contentContainerStyle={styles.container} accessibilityRole="none">
      {renderForm()}
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  container: { flexGrow: 1, padding: theme.spacing.lg, backgroundColor: theme.colors.background },
  text: { ...theme.typography.bodyMedium, marginBottom: theme.spacing.md },
  heading: { ...theme.typography.h2, color: theme.colors.onSurface, marginBottom: theme.spacing.md },
  form: { marginTop: theme.spacing.md },
  image: { width: 200, height: 200, marginBottom: theme.spacing.sm },
  placeholderContainer: {
    borderWidth: 1,
    borderColor: theme.colors.secondary,
    borderRadius: theme.radii.md,
    padding: theme.spacing.lg,
    alignItems: 'center',
    justifyContent: 'center',
    marginBottom: theme.spacing.md,
  },
  placeholderText: { ...theme.typography.bodyMedium, color: theme.colors.secondary },
});"}

{"path": "expo-app/src/screens/SignUpScreen.tsx", "content": "import React, { useState } from 'react';
import { View, Text, StyleSheet, ActivityIndicator } from 'react-native';
import { useNavigation } from '@react-navigation/native';
import axios from 'axios';
import PrimaryButton from '../components/ui/PrimaryButton';
import FormField from '../components/ui/FormField';
import { saveToken } from '../auth';
import { API_URL } from '../config';
import { theme } from '../theme';
import { FontAwesome } from '@expo/vector-icons';
import LoadingOverlay from '../components/LoadingOverlay';
import Screen from '../components/ui/Screen';
import { Button } from 'react-native-paper';
import { TextInput } from 'react-native-paper';

export default function SignUpScreen() {
  const navigation = useNavigation<any>();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [errorEmail, setErrorEmail] = useState('');
  const [errorPassword, setErrorPassword] = useState('');
  const [submissionError, setSubmissionError] = useState('');
  const [secureEntry, setSecureEntry] = useState(true);

  const validate = () => {
    let valid = true;
    if (!email || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
      setErrorEmail('Enter a valid email address.');
      valid = false;
    } else {
      setErrorEmail('');
    }
    if (password.length < 12 || !/[A-Z]/.test(password) || !/[a-z]/.test(password) || !/[0-9]/.test(password) || !/[^A-Za-z0-9]/.test(password)) {
      setErrorPassword('Password must be at least 12 characters, include uppercase, lowercase, number, and symbol.');
      valid = false;
    } else {
      setErrorPassword('');
    }
    return valid;
  };

  const handleSignup = async () => {
    if (!validate()) return;
    setLoading(true);
    try {
      const resp = await axios.post(`${API_URL}/auth/signup`, { email, password });
      const token = resp.data.access_token;
      await saveToken(token);
      navigation.reset({ index: 0, routes: [{ name: 'Main' }] });
    } catch (e) {
      setSubmissionError("We couldn't create your account. Please check the fields and try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Screen>
      <View style={styles.container}>
        {submissionError ? <Text style={styles.submissionError} accessibilityRole="alert">{submissionError}</Text> : null}
        <Text style={styles.title}>Create your account</Text>
        <FormField
          label="Email address"
          value={email}
          onChangeText={setEmail}
          error={!!errorEmail}
          helperText={errorEmail}
          keyboardType="email-address"
          accessibilityLabel="Email address"
        />
        <FormField
          label="Password"
          value={password}
          onChangeText={setPassword}
          error={!!errorPassword}
          helperText={errorPassword}
          secureTextEntry={secureEntry}
          accessibilityLabel={secureEntry ? "Show password" : "Hide password"}
          right={<TextInput.Icon icon={secureEntry ? 'eye-off' : 'eye'} onPress={() => setSecureEntry(!secureEntry)} accessibilityLabel={secureEntry ? 'Show password' : 'Hide password'} />}
        />
        <Text style={styles.helper}>12 + characters, uppercase, lowercase, number, symbol</Text>
        {loading ? (
          <ActivityIndicator size="large" color={theme.colors.primary} />
        ) : (
          <PrimaryButton title="Create account" onPress={handleSignup} accessibilityLabel="Create account" />
        )}
        <Button
          mode="text"
          onPress={() => navigation.navigate('SignIn')}
          accessibilityLabel="Already have an account? Log in"
          style={styles.link}
        >
          Already have an account? Log in
        </Button>
        {loading && <LoadingOverlay message="Creating account…" />}
      </View>
    </Screen>
  );
}

const styles = StyleSheet.create({
  container: { paddingBottom: theme.spacing.lg },
  title: { ...theme.typography.h2, color: theme.colors.onSurface, marginBottom: theme.spacing.lg },
  helper: { color: theme.colors.placeholder, ...theme.typography.caption, marginTop: theme.spacing.xs },
  link: { marginTop: theme.spacing.lg, alignSelf: 'center' },
  submissionError: { color: theme.colors.error, ...theme.typography.body, marginBottom: theme.spacing.sm },
});"}

{"path": "expo-app/src/screens/DashboardScreen.tsx", "content": "import React, { useEffect, useState } from 'react';
import { ActivityIndicator, StyleSheet, Text, View, Pressable } from 'react-native';
import axios from 'axios';
import { useNavigation, useIsFocused, useRoute } from '@react-navigation/native';
import { getToken } from '../auth';
import { API_URL } from '../config';
import { theme } from '../theme';
import PrimaryButton from '../components/ui/PrimaryButton';
import Screen from '../components/ui/Screen';
import SummaryCard from '../components/ui/SummaryCard';
import EmptyState from '../components/ui/EmptyState';
import { FontAwesome } from '@expo/vector-icons';

export default function DashboardScreen() {
  const navigation = useNavigation<any>();
  const route = useRoute<any>();
  const isFocused = useIsFocused();
  const [loading, setLoading] = useState(false);
  const [summary, setSummary] = useState<any>(null);
  const [receipts, setReceipts] = useState<any[]>([]);
  const [showMessage, setShowMessage] = useState(false);

  const fetchData = async () => {
    setLoading(true);
    try {
      const token = await getToken();
      const [summaryResp, receiptsResp] = await Promise.all([
        axios.get(`${API_URL}/dashboard`, { headers: { Authorization: `Bearer ${token}` } }),
        axios.get(`${API_URL}/receipts`, { headers: { Authorization: `Bearer ${token}` } }),
      ]);
      setSummary(summaryResp.data);
      setReceipts(receiptsResp.data);
    } catch (e) {
      // handle error
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (isFocused) {
      fetchData();
      if (route.params?.receiptSaved) {
        setShowMessage(true);
        navigation.setParams({ receiptSaved: false });
      }
    }
  }, [isFocused, route.params?.receiptSaved]);

  useEffect(() => {
    if (showMessage) {
      const timer = setTimeout(() => setShowMessage(false), 3000);
      return () => clearTimeout(timer);
    }
  }, [showMessage]);

  if (loading) {
    return (
      <View style={styles.center} accessibilityRole="none">
        <ActivityIndicator size="large" color={theme.colors.primary} />
        <Text style={styles.loadingText}>Loading summary…</Text>
      </View>
    );
  }

  const empty = !summary || (summary.income === 0 && summary.expenses === 0 && summary.mileage_deduction === 0 && summary.estimated_tax === 0);

  return (
    <Screen scroll>
      {showMessage && <Text style={styles.toast} accessibilityRole="alert">Receipt saved.</Text>}
      {empty ? (
        <EmptyState
          title="No data yet"
          description="You haven’t added any receipts or mileage yet. Tap the + button to get started."
          ctaLabel="Add first receipt"
          onPressCTA={() => navigation.navigate('ReceiptCapture')}
        />
      ) : (
        <>
          <View style={styles.cards}>
            <SummaryCard title="Income" value={`$${summary.income.toFixed(2)}`} accessibilityLabel="Income" />
            <SummaryCard title="Expenses" value={`$${summary.expenses.toFixed(2)}`} accessibilityLabel="Expenses" />
            <SummaryCard title="Mileage deduction" value={`$${summary.mileage_deduction.toFixed(2)}`} accessibilityLabel="Mileage deduction" />
            <SummaryCard title="Estimated tax" value={`$${summary.estimated_tax.toFixed(2)}`} accessibilityLabel="Estimated tax" />
          </View>
          <View style={styles.receiptList}>
            {receipts.map((r) => (
              <View key={r.id} style={styles.receiptItem} accessibilityLabel={`Receipt ${r.id}`}>
                <Text style={styles.receiptAmount}>{r.amount}</Text>
                <Text style={styles.receiptCategory}>{r.category}</Text>
              </View>
            ))}
          </View>
        </>
      )}
      <Pressable
        onPress={() => navigation.navigate('ReceiptCapture')}
        accessibilityLabel="Add receipt"
        accessibilityRole="button"
        style={styles.fabButton}
      >
        <FontAwesome name="plus" size={24} color={theme.colors.onAccent} accessible={false} />
      </Pressable>
    </Screen>
  );
}

const styles = StyleSheet.create({
  center: { flex: 1, justifyContent: 'center', alignItems: 'center' },
  loadingText: { marginTop: theme.spacing.md, ...theme.typography.bodyMedium },
  toast: { backgroundColor: theme.colors.success, color: theme.colors.onSuccess, padding: theme.spacing.sm, marginBottom: theme.spacing.md, textAlign: 'center', ...theme.typography.bodyMedium },
  cards: { flexDirection: 'column' },
  receiptList: { marginTop: theme.spacing.lg },
  receiptItem: { flexDirection: 'row', justifyContent: 'space-between', paddingVertical: theme.spacing.sm, borderBottomWidth: 1, borderBottomColor: theme.colors.outline },
  receiptAmount: { ...theme.typography.bodyMedium, color: theme.colors.onSurface },
  receiptCategory: { ...theme.typography.bodyMedium, color: theme.colors.secondary },
  fabButton: {
    position: 'absolute',
    right: theme.spacing.lg,
    bottom: theme.spacing.lg,
    width: 56,
    height: 56,
    borderRadius: 28,
    backgroundColor: theme.colors.accent,
    alignItems: 'center',
    justifyContent: 'center',
  },
});"}

