# Let's read all files in expo-app/src/screens and search for style definitions with literal values that aren't theme references.
files = []
for root, dirs, filenames in os.walk('expo-app/src/screens'):
    for f in filenames:
        if f.endswith('.tsx'):
            files.append(os.path.join(root, f))

def find_issues():
    issues = []
    for path in files:
        content = open(path).read()
        # Find any style object using numbers directly for fontSize, color etc.
        # We'll approximate: look for 'fontSize:' not containing theme.
        for m in re.finditer(r'fontSize\s*:\s*\d+', content):
            # record line number
            line = content[:m.start()].count('\n') + 1
            issues.append((path, line, m.group()))
        for m in re.finditer(r'color\s*:\s*[^\s,}]+', content):
            # see if it's a theme color reference (theme.colors.*) else capture.
            val = m.group().split(':')[1].strip()
            if not val.startswith('theme.colors'):
                line = content[:m.start()].count('\n') + 1
                issues.append((path, line, f'color: {val}'))
    return issues

issues = find_issues()
print(json.dumps(issues, indent=2))"
}

